rule.example:
// Bad — written out inline, whatever the namespace
return s.toLowerCase(java.util.Locale.ROOT);
throw new ClientErrorException(new io.dropwizard.jersey.errors.ErrorMessage(409, msg));

// Good — imported at the top of the file
import java.util.Locale;
import io.dropwizard.jersey.errors.ErrorMessage;
...
return s.toLowerCase(Locale.ROOT);
throw new ClientErrorException(new ErrorMessage(409, msg));

// Allowed — genuine simple-name collision, suppressed with a reason
import java.util.Date;
...
java.sql.Date sqlDate; // NOPMD - collides with the imported java.util.Date

// Not an inline FQN — nested-type access, not reported
@JsonView({Alert.View.Public.class, Alert.View.Write.class})
